def solve_near_numbers_and_sum():
    solutions = []

    N_range = range(1, 11) 
    E_range = range(1, 6)  

    for n_B in N_range:
        for a in E_range:
            B = n_B**a + 1

            for n_T in N_range:
                for b in E_range:
                    T = n_T**b + 1

                    target_S_c = (n_B**a) + (n_T**b) + 1

                    for n_S in N_range:
                        for c in E_range:
                            S_c = n_S**c

                            if target_S_c == S_c:
                                B_val = n_B**a + 1
                                T_val = n_T**b + 1
                                S_val = n_S**c + 1

                                if B_val + T_val == S_val:
                                    solutions.append(S_val)

    total_sum = sum(solutions)
    return total_sum

total_sum_S = solve_near_numbers_and_sum()

# The required sum is Sum(B_i + T_i + S_i) = Sum(S_i + S_i) = 2 * Sum(S_i)
final_evaluation = 2 * total_sum_S

print(f"Total Sum of S_i: {total_sum_S}")
print(f"Final Evaluation (2 * Total Sum of S_i): {final_evaluation}")
